# AI generated from scripts.md; do not edit by hand.
import sys as _sys
if _sys.version_info < (3, 14):
    _sys.exit("this needs Python 3.14+ (argparse color=False); found " + ".".join(map(str, _sys.version_info[:3])))
import argparse, json, re, sys, time
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

def _load_config():
    """Config file (--config arg, else $PRDOCS_CONFIG, else ROOT/active-config.cfg).
    Format: key=value lines; `repo=repos/<name>.md` names the repo file."""
    import os, sys
    path = os.environ.get("PRDOCS_CONFIG") or ROOT / "active-config.cfg"
    for i, x in enumerate(sys.argv):
        if x == "--config" and i + 1 < len(sys.argv):
            path = sys.argv[i + 1]
        elif x.startswith("--config="):
            path = x.split("=", 1)[1]
    path = Path(path).resolve()
    if not path.is_file():
        sys.exit(f"config file not found: {path}")
    kv = {}
    for line in path.read_text().splitlines():
        line = line.strip()
        if line and not line.startswith("#") and "=" in line:
            k, v = line.split("=", 1)
            kv[k.strip()] = v.strip()
    if "repo" not in kv:
        sys.exit(f"{path}: missing repo=<file>")
    return path, (ROOT / kv["repo"]).resolve()

CONFIG_FILE, REPO_FILE = _load_config()
import os as _os
_os.environ["PRDOCS_CONFIG"] = str(CONFIG_FILE)  # inherited by child scripts

def default_repo():
    m = re.search(r"github\.com/([\w.-]+)/([\w.-]+)", REPO_FILE.read_text())
    return f"{m[1]}/{m[2]}"

RESPONSE = re.compile(r"^c(\d+):\s*(.*)$")


def split_notes(notes, count):
    """General notes, and the `c<i>: ...` reply to each of `count` comments."""
    general, replies = [], [""] * count
    for line in notes.splitlines():
        m = RESPONSE.match(line)
        if m and 1 <= int(m[1]) <= count:
            replies[int(m[1]) - 1] = m[2].strip()
        else:
            general.append(line)
    return "\n".join(general).strip(), replies


def one(text):
    return " ".join(str(text).split())


def main():
    p = argparse.ArgumentParser(color=False)
    p.add_argument("--config", help="config file naming the repo file (default: active-config.cfg)")
    p.add_argument("run_id")
    p.add_argument("pr", type=int)
    p.add_argument("--repo", default=default_repo().replace("/", "_"))
    a = p.parse_args()

    out_dir = ROOT / "learning" / "interactive-feedback" / a.repo
    for old in out_dir.glob(f"{a.pr}-[0-9]*.md"):  # not the diff examples, <pr>-example-*
        old.unlink()
    grade = ROOT / "grades" / a.repo / f"{a.pr}.txt"
    result = ROOT / "results" / a.repo / a.run_id / f"{a.pr}.json"
    if not grade.exists() or not result.exists():
        return
    head, _, notes = grade.read_text().partition("notes:")
    mine = head.partition(":")[2].strip()
    res = json.loads(result.read_text())
    comments = [c if isinstance(c, dict) else {"sentiment": None, "text": c}
                for c in res.get("comments", [])]
    general, replies = split_notes(notes.strip(), len(comments))
    answered = [(c, r) for c, r in zip(comments, replies) if r]
    if not (mine or general or answered):
        return
    meta_file = ROOT / "data" / a.repo / "prs" / str(a.pr) / "meta.json"
    title = json.loads(meta_file.read_text()).get("title", "") if meta_file.exists() else ""
    stamp = time.strftime("%Y%m%d-%H%M%S")
    lines = [f"<!-- AI generated by scripts/extract_feedback.py from grades/{a.repo}/{a.pr}.txt -->",
             f"# Feedback on PR {a.pr}: {one(title)}", "",
             f"- repo: {a.repo.replace('_', '/', 1)}", f"- run: {a.run_id}", f"- saved: {time.strftime('%Y-%m-%d %H:%M:%S')}"]
    if res.get("overall") is not None:
        lines.append(f"- grader overall: {res['overall']}/5")
    if mine:
        lines.append(f"- reviewer grade: {mine}/5")
    for c, r in answered:
        s = f" [sentiment {c['sentiment']}]" if c.get("sentiment") else ""
        lines += ["", f"## Q: {one(c['text'])}{s}", f"A: {one(r)}"]
    if general:
        lines += ["", "## Notes", general]
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / f"{a.pr}-{stamp}.md").write_text("\n".join(lines) + "\n")
    print("wrote", f"{a.pr}-{stamp}.md")


main()
